import { course } from './course-data.js';
import { checkAnswer, emptyProgress, xpFor, coinsFor, awardsSummary, levelFromXP, parseNumber } from './logic.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rich=s=>esc(s??'').replace(/\*\*(.+?)\*\*/gs,'<strong>$1</strong>').replace(/\n/g,'<br>');
const euro=(n,d=2)=>Number(n).toLocaleString('de-DE',{minimumFractionDigits:d,maximumFractionDigits:d})+' €';
const fmt=n=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:2});
const questions=new Map(course.questions.map(q=>[q.id,q]));
const products=new Map(course.items.map(x=>[x.id,x]));
const moduleIds=course.modules.map(m=>m.id);
const STORE='preisgrenzen-guest-v1';
function readGuest(){try{const x=JSON.parse(localStorage.getItem(STORE));return {...emptyProgress(),...x}}catch{return emptyProgress()}}
const state={user:null,guest:readGuest(),page:'home',module:'kosten',qAt:0,feedback:{},revealed:{},draft:{},hint:{},authMode:'register',authRole:'student',modal:null,teacherUsers:[],teacherSelected:null,lab:'betrieb',labs:{p:46,kv:22,kf:6400,x:400,gk:8000,fixedPercent:75,ek:12000,qty:500,fm:60,fl:30,mgk:20,fgk:50,vw:10,vt:5,fixShare:80},busy:false};
const progress=()=>state.user?.progress||state.guest;
const identity=()=>state.user?.nickname||'Gast-Profil';
const summary=()=>{const a=awardsSummary(progress());const spent=(progress().owned||[]).reduce((s,id)=>s+(products.get(id)?.cost||0),0);return {xp:a.xp,coins:a.earnedCoins-spent,level:levelFromXP(a.xp)}};
const done=q=>['correct','self'].includes(progress().answers[q.id]?.status);
const doneCount=mod=>course.questions.filter(q=>(!mod||q.module===mod)&&!q.bonus&&done(q)).length;
const moduleQ=mod=>course.questions.filter(q=>q.module===mod);
const allQuestionCount=course.questions.filter(q=>!q.bonus).length;
const svgIcon=(n)=>({home:'🏠',path:'🧭',lab:'📈',shop:'🛍️',gallery:'🎨',glossary:'📚',test:'🏆',checklist:'✅',journal:'📄',teacher:'🧑‍🏫'}[n]||'⭐');
const achievements=()=>{
 const p=progress(),n=Object.keys(p.awards||{}).length,bon=Object.keys(p.awards||{}).filter(id=>questions.get(id)?.bonus).length;
 return [
 ['🌱','Erster Schritt',n>=1],['📦','Kosten-Scout',doneCount('kosten')===8],
 ['🎯','Grenzgänger',doneCount('kurz')===8],['🧮','Kalkulationsprofi',doneCount('zuschlag')===8],
 ['⭐','Bonusjäger',bon>=5],['📚','Lernmarathon',n>=50],
 ['🏆','Finale gemeistert',doneCount('test')===12],
 ['✅','Selbstcheck vollständig',Object.values(p.checklist||{}).filter(x=>x.done).length===10]
 ];
};
const equipped=()=>{let p=progress().equipped||{},avatar=products.get(p.avatar)||products.get('base');return {avatar,pet:products.get(p.pet),outfit:products.get(p.outfit)}};
function toast(m){const old=$('#toast');old?.remove();const el=document.createElement('div');el.className='toast';el.id='toast';el.role='status';el.textContent=m;document.body.append(el);setTimeout(()=>el.remove(),4000)}
function route(page,mod){state.page=page;if(mod)state.module=mod;const current=page==='test'?'test':mod;const firstIncomplete=current?moduleQ(current).findIndex(q=>!done(q)):0;state.qAt=firstIncomplete>=0?firstIncomplete:0;state.feedback={};state.revealed={};window.scrollTo({top:0,behavior:'instant'});render()}
function navButtons(){let items=[['home','Übersicht'],['path','Lernpfad'],['lab','Kostenlabor'],['test','Abschlusstest'],['shop','XP-Shop'],['gallery','Avatar-Galerie'],['glossary','Glossar'],['checklist','Selbstcheck'],['journal','Mein PDF']];if(state.user?.role==='teacher')items.push(['teacher','Lehrbereich']);return items.map(([id,name])=>`<button class="nav-btn ${state.page===id?'active':''}" data-nav="${id}"><span aria-hidden="true">${svgIcon(id)}</span>${name}</button>`).join('')}
function footer(){return `<footer class="footer"><details><summary>KI-Nachweis & Hinweise</summary><p>KI-Nachweis: Die Konzeption, Gestaltung und technische Überarbeitung dieses Kurses erfolgten am <strong>29.10.2026</strong> unter Nutzung von <strong>ChatGPT (OpenAI, GPT-6)</strong>. Das KI-Werkzeug wurde insbesondere zur Strukturierung von Kursinhalten sowie zur Erstellung und Überarbeitung von HTML und CSS eingesetzt. Einzelne Grafiken wurden ebenfalls KI-gestützt erstellt. Die fachliche und redaktionelle Prüfung sowie die abschließende Auswahl und Anpassung der Inhalte erfolgten durch die kurserstellende Lehrkraft. Die Kennzeichnung orientiert sich an den Empfehlungen der Universität Hamburg zum Umgang mit generativer KI.</p><p>Fiktiver Fallbetrieb: LoopLab GmbH, Leipzig. Lernfragen und Rechenbeispiele sind didaktisch neu erstellt; die hochgeladenen Grafiken dienen als Lernmaterial. Im Kostenmodell werden proportionale variable Kosten und unveränderte Fixkosten angenommen, soweit nichts anderes angegeben ist. Dieser Kurs ersetzt keine individuelle finanzielle Beratung. Datenschutz: Nickname, Klasse, Passwort-Hash und Lernstand werden bei Anmeldung in Netlify Blobs gespeichert; Gastdaten bleiben im Browser. Es wird keine E-Mail benötigt. Verantwortliche Stelle ist die bereitstellende Lehrkraft/Schule; ergänzen Sie vor der öffentlichen Veröffentlichung Ihr eigenes Impressum und Ihre Datenschutzhinweise.</p></details><div>LoopLab-Mission · FOS VBWL/RW · © Lernprojekt · <a href="https://docs.netlify.com/build/data-and-storage/netlify-blobs/" target="_blank" rel="noopener">Datenspeicherung: Netlify Blobs</a></div></footer>`}
function render(){const ss=summary(),av=equipped();$('#app').innerHTML=`<div class="shell"><aside class="side"><div class="brand"><span class="brandicon">🎯</span><span>Preisgrenzen</span></div><div class="avcard"><div class="avface">${av.avatar.emoji}${av.pet?`<span class="tiny-pet">${av.pet.emoji}</span>`:''}</div><div><strong>${esc(identity())}</strong><div class="level">Level ${ss.level} · ${ss.xp} XP</div><div class="xpbar"><span style="width:${Math.min(100,(ss.xp%150)/150*100)}%"></span></div></div></div><nav class="sidenav" aria-label="Hauptnavigation">${navButtons()}</nav><div class="side-foot">📦 Fiktiver Industriebetrieb in Leipzig<br>🎮 Lernen · Anwenden · Entscheiden</div></aside><main class="main"><header class="topbar"><div class="muted small">${state.user?`Klasse <b>${esc(state.user.schoolClass)}</b> · ${state.user.role==='teacher'?'Lehrkraft':'Schülerkonto'}`:'Gastmodus · ohne Anmeldung'}</div><div class="topright"><button class="stat-pill" data-nav="gallery" title="Ihre Avatar-Galerie">${av.avatar.emoji}${av.pet?av.pet.emoji:""}</button><span class="stat-pill">⭐ ${ss.xp} XP</span><span class="stat-pill">🪙 ${ss.coins}</span>${state.user?`<button class="btn small light" data-action="account">Konto</button>`:`<button class="btn small" data-action="auth">Anmelden</button>`}</div></header><div class="content">${renderPage()}${footer()}</div></main></div>${renderModal()}`;if(state.page==='lab')renderLabOutput()}
function renderPage(){return ({home:homePage,path:pathPage,lesson:lessonPage,lab:labPage,shop:shopPage,gallery:galleryPage,glossary:glossaryPage,test:testPage,checklist:checklistPage,journal:journalPage,teacher:teacherPage}[state.page]||homePage)()}
function homePage(){let s=summary();const chosen=course.modules.find(m=>m.id===state.module)||course.modules[0];return `<section><div class="hero"><div><div class="eyebrow">FOS · Volks- und Betriebswirtschaftslehre mit Rechnungswesen</div><h1>Die Preisgrenzen-Mission</h1><p class="lead">Sie übernehmen die Kostenrechnung der <strong>LoopLab GmbH</strong> in Leipzig. Wie niedrig darf der Verkaufspreis eines Smartphone-Halters sein, ohne dass die Wirtschaftlichkeit verloren geht?</p><div class="actions"><button class="btn" data-nav="path">🧭 Lernpfad starten</button><button class="btn light" data-nav="lab">📊 Kosten live verändern</button></div><div class="chiprow"><span class="tag green">10 Kapitel + Abschlusstest</span><span class="tag">112 Aufgaben inkl. Bonus</span><span class="tag gold">Interaktive Simulationen</span></div></div><figure style="margin:0"><img src="/assets/comic.webp" alt="Modern-Comic: Besprechung über verschiedene Verkaufspreise in einer Fertigung"><figcaption class="fine">Einstiegsillustration mit eigenständigen Preisbeispielen; der LoopLab-Fall nutzt andere Werte.</figcaption></figure></div><div class="statgrid"><div class="statbox"><span class="muted">Bearbeitet</span><strong>${doneCount()} / ${allQuestionCount}</strong><div class="mini-progress"><span style="width:${100*doneCount()/allQuestionCount}%"></span></div></div><div class="statbox"><span class="muted">Level</span><strong>${s.level}</strong>XP sammeln</div><div class="statbox"><span class="muted">Münzen</span><strong>${s.coins} 🪙</strong>Avatare & Haustiere</div><div class="statbox"><span class="muted">Gespeichert</span><strong>${state.user?'☁️':'📱'}</strong>${state.user?'geräteübergreifend':'nur dieses Gerät'}</div></div><h2>Ihre Lernreise</h2><div class="grid">${course.modules.slice(0,6).map(moduleCard).join('')}</div><div class="actions"><button class="btn light" data-nav="path">Alle Kapitel anzeigen →</button></div><h2>🏅 Ihre Auszeichnungen</h2><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr))">${achievements().map(([emoji,name,earned])=>`<div class="card" style="opacity:${earned?'1':'.5'};text-align:center;padding:15px"><div style="font-size:2rem">${emoji}</div><strong>${esc(name)}</strong><div class="fine">${earned?'✓ Freigeschaltet':'Noch gesperrt'}</div></div>`).join('')}</div><div class="grid two"><article class="card"><h3>🎛️ Das Kostenlabor</h3><p>Verändern Sie Preise, Mengen, Fixkosten oder Zuschlagssätze und beobachten Sie Diagramme, Preisuntergrenzen und Gewinn live.</p><button class="btn light" data-nav="lab">Simulation öffnen</button></article><article class="card"><h3>🏆 Lernen lohnt sich</h3><p>Richtig gelöste Aufgaben bringen XP und Münzen. Erreichen Sie neue Level, kaufen Sie virtuelle Haustiere und gestalten Sie Ihren Avatar.</p><button class="btn light" data-nav="shop">Shop besuchen</button></article></div></section>`}
function moduleCard(m){let qs=moduleQ(m.id).filter(q=>!q.bonus),d=doneCount(m.id);return `<article class="card hover"><div class="module-head"><span class="chapter-emoji">${m.emoji}</span><span class="tag ${d===qs.length?'green':''}">${d}/${qs.length} erledigt</span></div><h3>${esc(m.title)}</h3><p class="muted">${esc(m.lead)}</p><div class="mini-progress"><span style="width:${100*d/qs.length}%"></span></div><button class="btn light" data-module="${m.id}">${m.id==='test'?'Test bearbeiten':'Kapitel öffnen'} →</button></article>`}
function pathPage(){return `<section><div class="eyebrow">Ihre Stationen</div><h1>Lernpfad</h1><p>Jedes Kapitel enthält Erklärungen, Beispiele, Übungsaufgaben, anspruchsvollere Entscheidungen und Bonus-Missionen. Zu jeder Aufgabe können Sie die Musterlösung anzeigen.</p><div class="grid">${course.modules.filter(m=>m.id!=='test').map(moduleCard).join('')}</div></section>`}
function imageBlock(m){return `<figure style="margin:0"><img class="lesson-photo" loading="lazy" src="/assets/${m.image}.webp" alt="Fachliche Abbildung zum Thema ${esc(m.title)}"><figcaption class="fine">${m.image==='auslastung'?'Original-Schaubild aus dem Unterrichtsmaterial (schematisch). Im vereinfachten Modell fällt die langfristige PUG bis zur Kapazitätsgrenze monoton.':'Lernabbildung: '+esc(m.title)+'.'} Dynamische, rechnerisch überprüfbare Modelle finden Sie im Kostenlabor.</figcaption></figure>`}
function lessonPage(testMode=false){let mod=course.modules.find(m=>m.id===(testMode?'test':state.module))||course.modules[0],arr=moduleQ(mod.id),idx=Math.max(0,Math.min(state.qAt,arr.length-1)),q=arr[idx];return `<section><button class="btn small light back" data-nav="${testMode?'home':'path'}">← Übersicht</button><div class="eyebrow">${testMode?'Abschlussprüfung im Kurs':`Kapitel ${course.modules.indexOf(mod)+1} von 10`}</div><h1>${mod.emoji} ${esc(mod.title)}</h1><p class="muted">${esc(mod.lead)}</p><div class="lesson-layout"><div><article class="card"><h2>Verstehen & Anwenden</h2><p>${rich(mod.body)}</p><div class="definitions">${mod.bullets.map(b=>`<div class="definition">${rich(b)}</div>`).join('')}</div><div class="example"><strong>📌 Rechenbeispiel</strong><p>${rich(mod.example)}</p></div></article>${qCard(q,idx,arr.length)}</div><aside class="lesson-index"><h3>Aufgaben-Navigator</h3>${arr.map((x,i)=>`<button class="index-item ${idx===i?'active':''}" data-q-index="${i}">${done(x)?'✅':'○'} ${i+1}. ${x.bonus?'⭐ Bonus · ':''}${'AFB '+x.afb} · ${esc(x.type==='text'?'Erklären / beurteilen':x.type==='number'?'Berechnen':x.type==='drag'?'Zuordnen':'Prüfen')}</button>`).join('')}<hr class="mutedline">${imageBlock(mod)}</aside></div></section>`}
const testPage=()=>lessonPage(true);
function qCard(q,index,count){const old=progress().answers[q.id],result=state.feedback[q.id],revealed=state.revealed[q.id];return `<article class="question" id="question"><div class="module-head"><span class="tag badge-afb">AFB ${q.afb} · ${index+1} / ${count}</span><span>${q.bonus?'<span class="tag gold">⭐ Bonus-Mission</span>':''} <span class="tag">+${xpFor(q)} XP</span></span></div><h3>${q.bonus?'Bonus-Mission':'Übungsaufgabe'}</h3><div class="prompt">${rich(q.prompt)}</div>${inputFor(q)}<div class="actions">${q.type!=='text'?`<button class="btn" data-action="submit" data-q="${q.id}">✓ Antwort prüfen</button>`:`<button class="btn" data-action="submit" data-q="${q.id}">✍️ Antwort festhalten</button>`}<button class="btn light" data-action="solution-request" data-q="${q.id}">👁 Musterlösung</button><button class="btn light" data-action="hint" data-q="${q.id}">💡 Hilfe</button></div>${state.hint[q.id]?`<div class="help"><strong>Denkanstoß:</strong> ${esc(q.hint||'Welche Angaben sind gegeben? Überlegen Sie zuerst, welcher Fachbegriff oder welche Formel benötigt wird.')}</div>`:''}${result!==undefined?`<div class="feedback ${result===false?'bad':''}" role="status">${result===true?'✅ Korrekt! XP und Münzen wurden bei erstmaligem Erfolg gutgeschrieben.':result===false?'✍️ Noch nicht richtig. Prüfen Sie Ihre Eingabe und versuchen Sie es erneut.':'📝 Antwort gespeichert. Vergleichen Sie Ihre Begründung mit der Musterlösung und entscheiden Sie selbst.'}</div>`:''}${old&&!state.feedback[q.id]?`<div class="feedback ${old.status==='wrong'?'bad':''}">${done(q)?'✅ Bereits bearbeitet und als richtig markiert.':'📝 Vorherige Antwort vorhanden.'}</div>`:''}${revealed?`<div class="solution"><strong>📘 Musterlösung mit Rechenweg</strong><p>${rich(q.solution)}</p>${q.type==='text'?`<div class="actions"><button class="btn" data-action="selfcorrect" data-q="${q.id}">✓ Meine Antwort ist korrekt</button><button class="btn light" data-action="selfrevise" data-q="${q.id}">↻ Antwort überarbeiten</button></div>`:''}</div>`:''}<div class="actions"><button class="btn light" data-qprev="1" ${index===0?'disabled':''}>← Vorherige</button><button class="btn alt" data-qnext="1" ${index===count-1?'disabled':''}>Nächste Aufgabe →</button></div></article>`}
function currentDraft(q){if(Object.prototype.hasOwnProperty.call(state.draft,q.id))return state.draft[q.id];const old=progress().answers[q.id]?.answer;if(old!==undefined)return structuredClone(old);if(q.type==='order')return [...q.items].reverse();if(q.type==='multi')return [];if(['drag','match'].includes(q.type))return {};return q.type==='truefalse'?null:''}
function inputFor(q){const d=currentDraft(q);if(q.type==='number')return `<div class="form-row"><label for="numanswer">Ihre Berechnung ${esc(q.unit||'')}</label><input class="answer-input" id="numanswer" type="text" inputmode="decimal" placeholder="Zahlenwert eingeben, z. B. 24,50" value="${esc(d)}" data-draft="${q.id}"></div>`;
 if(q.type==='text')return `<div class="form-row"><label for="textanswer">Ihre Begründung</label><textarea class="answer-input" id="textanswer" placeholder="Formulieren Sie Ihre Antwort in eigenen Worten." data-draft="${q.id}">${esc(d)}</textarea><p class="fine">Längere Antworten werden nicht automatisch bewertet. Nach dem Lösungsvergleich schätzen Sie Ihre Antwort selbst ein.</p></div>`;
 if(q.type==='single'||q.type==='multi'||q.type==='truefalse'){let choices=q.type==='truefalse'?[[true,'Richtig'],[false,'Falsch']]:(q.options||[]).map(x=>[x,x]);let multi=q.type==='multi';return `<div class="options" role="group" aria-label="Antwortmöglichkeiten">${choices.map(([val,label],i)=>{let checked=multi?Array.isArray(d)&&d.includes(val):d===val;return `<label class="option"><input type="${multi?'checkbox':'radio'}" name="q-${q.id}" data-choice="${q.id}" value="${esc(String(val))}" ${checked?'checked':''}><span>${esc(label)}</span></label>`}).join('')}</div>`}
 if(q.type==='match')return `<div class="table-scroll"><table class="shuffle-table"><thead><tr><th>Begriff / Situation</th><th>Zuordnung</th></tr></thead><tbody>${Object.keys(q.pairs).map(k=>`<tr><td>${esc(k)}</td><td><select class="answer-input" data-map="${q.id}" data-item="${esc(k)}"><option value="">Bitte wählen</option>${[...new Set(Object.values(q.pairs))].map(v=>`<option ${d[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`;
 if(q.type==='drag')return `<div class="formnotice">🖐 Ziehen Sie einen Begriff in die passende Kategorie. Auf mobilen Geräten können Sie die Kategorie auch auswählen.</div><div class="drag-grid"><div class="dropzone" data-drop="${q.id}" data-group=""><strong>Nicht zugeordnet</strong>${q.items.filter(item=>!d[item]).map(item=>`<div class="drag-token" draggable="true" data-dragtoken="${q.id}" data-item="${esc(item)}">↕ ${esc(item)}</div>`).join('')}</div>${q.groups.map(g=>`<div class="dropzone" data-drop="${q.id}" data-group="${esc(g)}"><strong>${esc(g)}</strong>${q.items.filter(item=>d[item]===g).map(item=>`<div class="drag-token" draggable="true" data-dragtoken="${q.id}" data-item="${esc(item)}">↕ ${esc(item)}</div>`).join('')}</div>`).join('')}</div><div class="options">${q.items.map(item=>`<label class="form-row">${esc(item)}<select class="answer-input" data-map="${q.id}" data-item="${esc(item)}"><option value="">Kategorie auswählen</option>${q.groups.map(g=>`<option ${d[item]===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label>`).join('')}</div>`;
 if(q.type==='order')return `<p class="muted small">Bringen Sie die Schritte durch Verschieben oder mit ↑ ↓ in die richtige Reihenfolge.</p>${d.map((item,i)=>`<div class="order-row" draggable="true" data-orderdrag="${q.id}" data-idx="${i}"><span><strong>${i+1}.</strong> ${esc(item)}</span><span class="row-btns"><button type="button" aria-label="Nach oben" data-move="${q.id}" data-pos="${i}" data-dir="-1">↑</button><button type="button" aria-label="Nach unten" data-move="${q.id}" data-pos="${i}" data-dir="1">↓</button></span></div>`).join('')}`;return ''}
function labPage(){let tabs=[['betrieb','Betriebsergebnis'],['preis','Preisampel'],['kosten','Kostenkurven'],['split','Kostenspaltung'],['kalk','Zuschlagskalkulation']];return `<section><div class="eyebrow">Interaktive Simulationen</div><h1>🎛️ Das Kostenlabor</h1><p>Verändern Sie die Regler und beobachten Sie unmittelbar, wie sich Kosten, Deckungsbeitrag, Preisuntergrenzen und Kostenverläufe verändern. <strong>Modellannahme:</strong> konstante Fixkosten und proportionale variable Kosten.</p><div class="labtabs">${tabs.map(([id,t])=>`<button class="${state.lab===id?'active':''}" data-lab="${id}">${t}</button>`).join('')}</div><div class="grid two"><article class="card"><h3>Werte verändern</h3>${labControls()}</article><div class="lab-visual" id="lab-output" aria-live="polite"></div></div></section>`}
function slide(key,label,min,max,step,unit='€'){return `<div class="slider-row"><label for="l-${key}">${label}</label><input id="l-${key}" type="range" data-slider="${key}" min="${min}" max="${max}" step="${step}" value="${state.labs[key]}"><output id="o-${key}">${fmt(state.labs[key])} ${unit}</output></div>`}
function labControls(){if(['betrieb','preis','kosten'].includes(state.lab))return slide('p','Verkaufspreis je Stück',0,100,1)+slide('kv','Variable Stückkosten',0,80,1)+slide('kf','Fixkosten je Monat',0,24000,200)+slide('x','Produktions-/Absatzmenge',100,1000,20,'Stück');if(state.lab==='split')return slide('ek','Variable Einzelkosten gesamt',0,30000,250)+slide('gk','Gemeinkosten gesamt',0,30000,250)+slide('fixedPercent','Fixer GK-Anteil',0,100,5,'%')+slide('qty','Menge',100,1500,50,'Stück');return slide('fm','Fertigungsmaterial / Stück',10,200,5)+slide('fl','Fertigungslöhne / Stück',5,150,5)+slide('mgk','MGK-Zuschlag',0,100,5,'%')+slide('fgk','FGK-Zuschlag',0,250,5,'%')+slide('vw','VwGK-Zuschlag',0,30,1,'%')+slide('vt','VtGK-Zuschlag',0,30,1,'%')+slide('fixShare','Fixer GK-Anteil',0,100,5,'%')}
function model(){const a=state.labs;return {g:a.kv+a.kf/a.x, db:a.p-a.kv, profit:(a.p-a.kv)*a.x-a.kf,rev:a.p*a.x,cost:a.kv*a.x+a.kf}}
function xyPoints(fn,xmin,xmax,step,ymax){let ar=[];for(let x=xmin;x<=xmax;x+=step){let y=fn(x);ar.push(`${(52+(x/xmax)*520).toFixed(1)},${(300-250*y/ymax).toFixed(1)}`)}return ar.join(' ')}
function graph(title,lines, xmax=1000){const maxY=Math.max(1,...lines.map(l=>l.fun(xmax)))*1.06;let axes=`<line x1="52" y1="40" x2="52" y2="302" stroke="#526c78" stroke-width="2"/><line x1="52" y1="302" x2="585" y2="302" stroke="#526c78" stroke-width="2"/>`;for(let i=0;i<5;i++){const y=300-i*62.5;axes+=`<line x1="52" y1="${y}" x2="572" y2="${y}" stroke="#e5eef1"/><text x="45" y="${y+4}" text-anchor="end" font-size="11" fill="#60727c">${fmt(maxY*i/4)}</text>`}axes+=`<text x="574" y="323" font-size="11" text-anchor="end">Menge (Stück)</text>`;return `<div class="muted small">${esc(title)}</div><svg viewBox="0 0 610 345" role="img" aria-label="Dynamisches Diagramm: ${esc(title)}">${axes}${lines.map(l=>`<polyline points="${xyPoints(l.fun,0,xmax,20,maxY)}" fill="none" stroke="${l.color}" stroke-width="3.5"/>`).join('')}</svg><div class="chiprow">${lines.map(l=>`<span class="chip"><span style="color:${l.color}">●</span> ${esc(l.label)}</span>`).join('')}</div>`}
function labMarkup(){const a=state.labs,m=model();if(state.lab==='betrieb')return `<h3>Gewinn = Umsatz − Gesamtkosten</h3><div class="statgrid" style="grid-template-columns:1fr 1fr"><div class="statbox"><span class="muted">Umsatz</span><strong>${euro(m.rev,0)}</strong></div><div class="statbox"><span class="muted">Gesamtkosten</span><strong>${euro(m.cost,0)}</strong></div><div class="statbox"><span class="muted">Stück-DB</span><strong>${euro(m.db)}</strong></div><div class="statbox"><span class="muted">Ergebnis</span><strong style="color:${m.profit>=0?'#208354':'#b4485b'}">${euro(m.profit,0)}</strong></div></div>${graph('Gesamtkosten und Umsatzerlöse', [{label:'Umsatz',color:'#269a7e',fun:x=>a.p*x},{label:'Gesamtkosten',color:'#d16f80',fun:x=>a.kv*x+a.kf}],1000)}<div class="mathbox">Betriebsergebnis = ${euro(m.rev,0)} (Umsatz) − ${euro(m.cost,0)} (Gesamtkosten) = <strong>${euro(m.profit,0)}</strong></div>`;
 if(state.lab==='preis'){let p=Math.max(a.p,a.kv,1),pct=Math.max(0,Math.min(100,a.kv/p*100)),db=a.p-a.kv;return `<h3>Wie tief darf der Preis fallen?</h3><p><strong>Kurzfristige PUG:</strong> ${euro(a.kv)} · <strong>Langfristige PUG:</strong> ${euro(m.g)}</p><div class="bar-rail"><div class="bar-seg" style="width:${pct}%;background:#f4bcbc">variable Kosten ${euro(a.kv)}</div>${db>0?`<div class="bar-seg" style="width:${100-pct}%;background:#c8edc3">DB ${euro(db)}</div>`:''}</div><div class="statbox"><span class="eyebrow">Preisampel</span><h2>${a.p<a.kv?'🔴 Unter kurzfristiger PUG':a.p===a.kv?'🟡 Genau auf kurzfristiger PUG':a.p<m.g?'🟠 Zwischen beiden Grenzen':a.p===m.g?'🟡 Auf langfristiger PUG':'🟢 Oberhalb langfristiger PUG'}</h2><p>Stückdeckungsbeitrag = ${euro(a.p)} (Preis) − ${euro(a.kv)} (variable Stückkosten) = <strong>${euro(db)}</strong></p><p>Stückergebnis = ${euro(a.p)} (Preis) − ${euro(m.g)} (Selbstkosten) = <strong>${euro(a.p-m.g)}</strong></p></div>`}
 if(state.lab==='kosten'){const ymax=Math.max(a.kv+a.kf/100,1);const yMax=Math.max(20,ymax*1.04);let pts=[];for(let x=100;x<=1000;x+=20)pts.push(`${52+(x/1000)*520},${300-(a.kv+a.kf/x)*240/yMax}`);let st=`<svg viewBox="0 0 610 345" role="img" aria-label="Verlauf beider Preisuntergrenzen"><line x1="52" y1="300" x2="584" y2="300" stroke="#71858c" stroke-width="2"/><line x1="52" y1="40" x2="52" y2="300" stroke="#71858c" stroke-width="2"/><polyline fill="none" stroke="#ce697d" stroke-width="4" points="${pts.join(' ')}"/><line x1="104" y1="${300-a.kv*240/yMax}" x2="573" y2="${300-a.kv*240/yMax}" stroke="#3c96b8" stroke-width="3" stroke-dasharray="8 4"/><line x1="${52+a.x/1000*520}" y1="55" x2="${52+a.x/1000*520}" y2="300" stroke="#748" stroke-dasharray="5 4"/><text x="59" y="25" fill="#445b65" font-size="14">€/Stück</text><text x="572" y="330" text-anchor="end" font-size="14">Menge</text></svg>`;return `<h3>Preisuntergrenze & Auslastung</h3>${st}<div class="chiprow"><span class="chip">🔴 Langfristige PUG</span><span class="chip">🔵 Kurzfristige PUG</span></div><div class="mathbox"><strong>Bei ${fmt(a.x)} Stück:</strong> Fixe Stückkosten = ${euro(a.kf,0)} (Fixkosten) ÷ ${fmt(a.x)} Stück (Menge) = ${euro(a.kf/a.x)}. Langfristige PUG = ${euro(a.kv)} + ${euro(a.kf/a.x)} = <strong>${euro(m.g)}</strong>.</div><p class="fine">Die rote Kurve sinkt bei höheren Stückzahlen (Fixkostendegression), während die kurzfristige PUG bei proportionalen variablen Kosten konstant bleibt.</p>`}
 if(state.lab==='split'){let vari=a.gk*(1-a.fixedPercent/100),fix=a.gk-vari,kurz=(a.ek+vari)/a.qty,lang=(a.ek+a.gk)/a.qty;return `<h3>Gemeinkosten zerlegen</h3><div class="bar-rail"><div class="bar-seg" style="width:${a.fixedPercent}%;background:#eab8b8">${a.fixedPercent}% fix</div><div class="bar-seg" style="width:${100-a.fixedPercent}%;background:#b9e1c9">${100-a.fixedPercent}% variabel</div></div><div class="statgrid" style="grid-template-columns:1fr 1fr"><div class="statbox">Fixe GK<strong>${euro(fix)}</strong></div><div class="statbox">Variable GK<strong>${euro(vari)}</strong></div><div class="statbox">Kurzfristige PUG<strong>${euro(kurz)}</strong></div><div class="statbox">Langfristige PUG<strong>${euro(lang)}</strong></div></div><div class="mathbox">Variable GK = ${euro(a.gk,0)} (gesamte GK) · ${100-a.fixedPercent}% (variabler Anteil) = ${euro(vari)}<br>Kurzfristige PUG = [${euro(a.ek,0)} (variable Einzelkosten) + ${euro(vari)} (variable GK)] ÷ ${fmt(a.qty)} Stück = <strong>${euro(kurz)}</strong></div>`}
 const mg=a.fm*a.mgk/100,fg=a.fl*a.fgk/100,hk=a.fm+a.fl+mg+fg,vw=hk*a.vw/100,vt=hk*a.vt/100,sk=hk+vw+vt,gk=mg+fg+vw+vt,kv=a.fm+a.fl+gk*(1-a.fixShare/100);
 return `<h3>Zuschlagskalkulation live</h3><div class="table-scroll"><table class="shuffle-table"><tbody>${[['Fertigungsmaterial',a.fm],['+ Materialgemeinkosten',mg],['+ Fertigungslöhne',a.fl],['+ Fertigungsgemeinkosten',fg],['= Herstellkosten',hk],['+ Verwaltungsgemeinkosten',vw],['+ Vertriebsgemeinkosten',vt],['= Selbstkosten / langfristige PUG',sk],['= Kurzfristige PUG',kv]].map(([k,v])=>`<tr><td>${esc(k)}</td><td><b>${euro(v)}</b></td></tr>`).join('')}</tbody></table></div><div class="mathbox">Variable GK = ${euro(gk)} (gesamte GK) · ${100-a.fixShare}% (variabler Anteil) = ${euro(gk*(1-a.fixShare/100))}<br>Kurzfristige PUG = ${euro(a.fm)} (FM) + ${euro(a.fl)} (FL) + ${euro(gk*(1-a.fixShare/100))} (variable GK) = <strong>${euro(kv)}</strong></div>`}
function renderLabOutput(){const el=$('#lab-output');if(el)el.innerHTML=labMarkup()}
function shopPage(){const s=summary(),owned=progress().owned||[];return `<section><div class="eyebrow">Belohnungen für Lernfortschritt</div><h1>🛍️ XP-Shop</h1><p>Mit richtigen Antworten sammeln Sie <strong>XP</strong> und Münzen. Die XP erhöhen Ihr Level und schalten Shop-Artikel frei; mit Münzen erwerben Sie Haustiere, Avatare und Outfits. Bereits gekaufte Gegenstände bleiben erhalten.</p><div class="actions"><span class="stat-pill">⭐ Level ${s.level}</span><span class="stat-pill">🪙 ${s.coins} Münzen verfügbar</span><button class="btn light" data-nav="gallery">Avatar ansehen</button></div><div class="shopgrid">${course.items.map(it=>`<article class="card shopitem"><span class="big-emoji">${it.emoji}</span><strong>${esc(it.name)}</strong><span class="tag">${it.kind==='avatar'?'Avatar':it.kind==='pet'?'Haustier':'Outfit'}</span><div class="muted small">Level ${it.level} · ${it.cost} 🪙</div><button class="btn small ${owned.includes(it.id)?'light':'gold'}" data-buy="${it.id}" ${owned.includes(it.id)||s.level<it.level||s.coins<it.cost?'disabled':''}>${owned.includes(it.id)?'Freigeschaltet':s.level<it.level?'Level fehlt':'Kaufen'}</button></article>`).join('')}</div></section>`}
function galleryPage(){const av=equipped(),owned=progress().owned||[];return `<section><div class="eyebrow">Ihr Lerncharakter</div><h1>🎨 Avatar-Galerie</h1><div class="avatar-stage"><div class="avatar-big">${av.avatar.emoji}</div><div class="avatar-acc">${av.pet?av.pet.emoji:'🐾'} ${av.outfit?av.outfit.emoji:'✨'}</div><h2>${esc(av.avatar.name)}</h2><span class="tag">${esc(identity())} · Level ${summary().level}</span></div><h2>Freigeschaltete Gegenstände</h2><div class="grid">${course.items.filter(i=>owned.includes(i.id)).map(i=>`<article class="card shopitem"><div class="big-emoji">${i.emoji}</div><strong>${esc(i.name)}</strong><span class="muted">${i.kind==='avatar'?'Avatar':i.kind==='pet'?'Haustier':'Outfit'}</span><button class="btn small light" data-equip="${i.id}">${progress().equipped?.[i.kind]===i.id?'✓ Ausgerüstet':'Ausrüsten'}</button></article>`).join('')}</div><div class="actions"><button class="btn" data-nav="shop">Mehr Gegenstände freischalten</button></div></section>`}
function glossaryPage(){return `<section><div class="eyebrow">Wissensspeicher</div><h1>📚 Begriffslexikon</h1><div class="form-row"><label for="gloss">Begriff suchen</label><input id="gloss" class="answer-input" type="search" placeholder="Begriff eingeben ..." value="${esc(state.gloss||'')}"></div><div class="grid two" id="glossgrid">${glossaryCards()}</div></section>`}
function glossaryCards(){return course.glossary.filter(([term,def])=>(term+' '+def).toLowerCase().includes((state.gloss||'').toLowerCase())).map(([term,def])=>`<article class="card"><h3>${esc(term)}</h3><p>${esc(def)}</p></article>`).join('')||'<p>Kein Begriff gefunden.</p>'}
function checklistPage(){let all=progress().checklist||{},n=Object.values(all).filter(x=>x.done).length;return `<section><div class="eyebrow">Reflexion</div><h1>✅ Kompetenz-Checkliste</h1><p>Schätzen Sie jede Kompetenz auf einer Skala von <strong>1 (noch unsicher)</strong> bis <strong>5 (sehr sicher)</strong> ein. Markieren Sie sie anschließend als erledigt; das lässt sich jederzeit zurücknehmen.</p><div class="statbox" style="margin-bottom:18px"><strong>${n} / ${course.checklist.length} erledigt</strong><div class="mini-progress"><span style="width:${n/course.checklist.length*100}%"></span></div></div>${course.checklist.map((t,i)=>{let v=all[i]||{value:3,done:false};return `<div class="card" style="margin:10px 0;${v.done?'background:#eaf8eb':''}"><div class="module-head"><strong>${esc(t)}</strong><span class="tag ${v.done?'green':''}">${v.done?'Erledigt':'Offen'}</span></div><div class="actions" style="align-items:center"><label>Selbsteinschätzung <select class="answer-input" style="width:auto" data-rating="${i}">${[1,2,3,4,5].map(x=>`<option ${v.value===x?'selected':''} value="${x}">${x} / 5</option>`).join('')}</select></label><button class="btn small ${v.done?'light':''}" data-check="${i}" data-done="${!v.done}">${v.done?'↩ Zurücksetzen':'✓ Als erledigt markieren'}</button></div></div>`}).join('')}</section>`}
function journalPage(){const answers=Object.keys(progress().answers||{}).length;return `<section><div class="eyebrow">Lernjournal</div><h1>📄 Alle Antworten als PDF</h1><p>Erstellen Sie ein zusammenhängendes, druckfreundliches Dokument mit Ihren <strong>bereits bearbeiteten Aufgaben</strong>, Ihren Antworten, Bearbeitungsstatus und den Musterlösungen.</p><div class="card"><h2>${answers} Aufgaben mit Antwort</h2><p>Nach dem Klick öffnet sich die Druckansicht. Wählen Sie dort <strong>„Als PDF sichern“</strong>, <strong>„Als PDF speichern“</strong> oder auf dem Mobilgerät die Druck-/Teilen-Funktion.</p><div class="actions"><button class="btn" data-action="print" ${answers?'':'disabled'}>📥 PDF-Druckansicht erstellen</button><button class="btn light" data-nav="checklist">✅ Selbsteinschätzung öffnen</button></div><p class="fine">Hinweis: Die PDF-Ausgabe verwendet die Druckfunktion Ihres Browsers; es werden keine Daten an einen fremden PDF-Dienst gesendet.</p></div></section>`}
function teacherPage(){if(state.user?.role!=='teacher')return homePage();let roster=state.teacherUsers,sel=state.teacherSelected,chosen=roster.find(u=>u.nickname===sel);let total=roster.filter(x=>x.role==='student').length;return `<section><div class="eyebrow">Lehrbereich · ${esc(state.user.schoolClass)}</div><h1>🧑‍🏫 Klassenübersicht</h1><p>Sie sehen ausschließlich die Nutzer und Lernstände Ihrer eigenen Klasse. Freitext-Antworten werden als <em>selbst geprüft</em> gekennzeichnet.</p><div class="actions"><button class="btn light" data-action="refresh-roster">↻ Aktualisieren</button><button class="btn warn" data-action="reset-class">Alle Lernstände dieser Klasse zurücksetzen</button></div><div class="statgrid"><div class="statbox">Schülerkonten<strong>${total}</strong></div><div class="statbox">Abgeschlossene Aufgaben<strong>${roster.filter(u=>u.role==='student').reduce((s,u)=>s+Object.values(u.progress?.answers||{}).filter(v=>['correct','self'].includes(v.status)).length,0)}</strong></div><div class="statbox">Durchschnittliche Lösungen<strong>${total?Math.round(roster.filter(u=>u.role==='student').reduce((s,u)=>s+Object.values(u.progress?.answers||{}).filter(v=>['correct','self'].includes(v.status)).length,0)/total):0}</strong></div><div class="statbox">Klasse<strong>${esc(state.user.schoolClass)}</strong></div></div><div class="card"><h2>Lernstände</h2><div class="table-scroll"><table class="shuffle-table"><thead><tr><th>Nickname</th><th>Rolle</th><th>Erledigt</th><th>XP</th><th>Details</th></tr></thead><tbody>${roster.map(u=>{let d=Object.values(u.progress?.answers||{}).filter(v=>['correct','self'].includes(v.status)).length;return `<tr><td>${esc(u.nickname)}</td><td>${u.role==='teacher'?'Lehrkraft':'Schüler/in'}</td><td>${d}/${allQuestionCount}</td><td>${awardsSummary(u.progress||emptyProgress()).xp}</td><td><button class="btn small light" data-student="${esc(u.nickname)}">Ansehen</button></td></tr>`}).join('')||'<tr><td colspan="5">Noch keine Konten vorhanden.</td></tr>'}</tbody></table></div></div>${chosen?`<div class="card" style="margin-top:20px"><h2>${esc(chosen.nickname)} – Lernjournal</h2><div class="actions"><button class="btn small light" data-teacher-op="resetProgress" data-nickname="${esc(chosen.nickname)}">Lernstand zurücksetzen</button>${chosen.role==='student'?`<button class="btn small light" data-teacher-op="resetPassword" data-nickname="${esc(chosen.nickname)}">Passwort zurücksetzen</button><button class="btn small warn" data-teacher-op="remove" data-nickname="${esc(chosen.nickname)}">Nutzer entfernen</button>`:''}</div><div class="table-scroll"><table class="shuffle-table"><thead><tr><th>Aufgabe</th><th>Antwort</th><th>Status</th></tr></thead><tbody>${Object.entries(chosen.progress?.answers||{}).map(([id,ans])=>`<tr><td>${esc(id)} · AFB ${questions.get(id)?.afb||'?'}</td><td>${esc(typeof ans.answer==='object'?JSON.stringify(ans.answer):ans.answer).slice(0,400)}</td><td>${ans.status==='self'?'Selbst geprüft':ans.status==='correct'?'Richtig':ans.status==='wrong'?'Nicht korrekt':'Entwurf'}</td></tr>`).join('')||'<tr><td colspan="3">Noch keine Aufgaben bearbeitet.</td></tr>'}</tbody></table></div></div>`:''}</section>`}
function renderModal(){if(!state.modal)return '';let k=state.modal.type;if(k==='auth')return `<div class="overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="mtitle"><button class="btn small light" style="float:right" data-action="close-modal">✕</button><h2 id="mtitle">${state.authMode==='register'?'Konto erstellen':'Anmelden'}</h2><p class="muted small">Mit Konto können Sie Ihren Lernstand auf unterschiedlichen Geräten fortsetzen. Nickname und Klasse sind bei jeder Anmeldung erforderlich.</p><form id="authform"><div class="form-row"><label for="anick">Nickname</label><input id="anick" name="nickname" class="answer-input" required minlength="3" maxlength="24" autocomplete="username" placeholder="Ihr gewünschter Nickname"></div><div class="form-row"><label for="aclass">Klasse</label><input id="aclass" name="schoolClass" class="answer-input" required maxlength="30" placeholder="z. B. FOS12A" value="${esc(state.lastClass||'')}"></div><div class="form-row"><label for="apw">Passwort</label><input id="apw" name="password" type="password" class="answer-input" required minlength="8" autocomplete="${state.authMode==='register'?'new-password':'current-password'}" placeholder="Mindestens 8 Zeichen"></div><div class="form-row"><label for="arole">Rolle</label><select id="arole" name="role" class="answer-input"><option value="student" ${state.authRole==='student'?'selected':''}>Schüler/in</option><option value="teacher" ${state.authRole==='teacher'?'selected':''}>Lehrkraft</option></select></div>${state.authMode==='register'?`<div class="form-row" id="teacherCodeRow"><label>Lehrercode (nur bei Registrierung als Lehrkraft)</label><input class="answer-input" name="teacherCode" placeholder="Code aus der Netlify-Konfiguration" autocomplete="off"></div>`:''}<div class="actions"><button class="btn" type="submit">${state.authMode==='register'?'Konto anlegen':'Einloggen'}</button><button type="button" class="btn light" data-action="auth-toggle">${state.authMode==='register'?'Bereits registriert? Anmelden':'Noch kein Konto? Registrieren'}</button></div></form></div></div>`;
 if(k==='confirm')return `<div class="overlay" id="overlay"><div class="modal" role="dialog" aria-modal="true"><h2>📘 Musterlösung anzeigen?</h2><p>Sie sind sich sicher? Vielleicht möchten Sie es noch einmal selbst versuchen. Wenn Sie die Musterlösung anzeigen, sehen Sie auch den Rechenweg.</p><div class="actions"><button class="btn light" data-action="close-modal">Noch einmal versuchen</button><button class="btn" data-action="reveal" data-q="${state.modal.q}">Musterlösung anzeigen</button></div></div></div>`;
 if(k==='account')return `<div class="overlay"><div class="modal" role="dialog" aria-modal="true"><button class="btn small light" style="float:right" data-action="close-modal">✕</button><h2>Mein Konto</h2><p>Nickname: <b>${esc(state.user.nickname)}</b><br>Klasse: <b>${esc(state.user.schoolClass)}</b></p><form id="passwordform"><div class="form-row"><label>Altes Passwort</label><input name="oldPassword" type="password" class="answer-input" required></div><div class="form-row"><label>Neues Passwort (mindestens 8 Zeichen)</label><input name="newPassword" type="password" class="answer-input" required minlength="8"></div><button class="btn" type="submit">Passwort ändern</button></form><hr class="mutedline">${Object.keys(state.guest.answers||{}).length?`<button class="btn light" data-action="importguest">📤 Gastfortschritt in dieses Konto übernehmen</button><p class="fine">Die Gastantworten werden serverseitig geprüft und erst dann mit XP belohnt.</p><hr class="mutedline">`:""}<button class="btn warn" data-action="logout">Abmelden</button></div></div>`;
 if(k==='confirmTeacher')return `<div class="overlay"><div class="modal"><h2>⚠️ Aktion bestätigen</h2><p>${esc(state.modal.message)}</p><div class="actions"><button class="btn light" data-action="close-modal">Abbrechen</button><button class="btn warn" data-action="teacher-execute">Ja, durchführen</button></div></div></div>`;
 if(k==='tempPassword')return `<div class="overlay"><div class="modal"><h2>Neues vorläufiges Passwort</h2><p>Bitte übermitteln Sie dieses Passwort ausschließlich an das betreffende Schülerkonto. Es wird hier nur einmal angezeigt.</p><div class="formnotice" style="font-size:1.3rem;font-weight:900;overflow-wrap:anywhere">${esc(state.modal.value)}</div><div class="actions"><button class="btn light" data-action="copytemp">Kopieren</button><button class="btn" data-action="close-modal">Schließen</button></div></div></div>`;
 return ''}
function openModal(type,other={}){state.modal={type,...other};render()}
async function api(action,body){const res=await fetch('/api/'+action,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store'});let data;try{data=await res.json()}catch{throw Error('Serverantwort unlesbar. Ist Netlify korrekt eingerichtet?')}if(!res.ok)throw Error(data.error||'Serverfehler');return data}
async function submit(q,selfCheck){let answer=currentDraft(q);if(q.type==='text')answer=String(answer||'');if(q.type==='number'&&(answer===''||Number.isNaN(parseNumber(answer)))){toast('Bitte einen gültigen Zahlenwert eingeben.');return}if(q.type==='text'&&!answer.trim()){toast('Bitte zuerst eine eigene Begründung eintragen.');return}
 try{let correct;if(state.user){const r=await api('answer',{id:q.id,answer,selfCheck});state.user=r.user;correct=r.correct}else{correct=q.type==='text'?selfCheck==='correct'?true:null:checkAnswer(q,answer);const prev=state.guest.answers[q.id];state.guest.answers[q.id]={answer,status:correct===true?(q.type==='text'?'self':'correct'):(prev&&['correct','self'].includes(prev.status))?prev.status:correct===null?'draft':'wrong',attempts:(prev?.attempts||0)+1,at:Date.now()};if(correct===true&&!state.guest.awards[q.id])state.guest.awards[q.id]={xp:xpFor(q),coins:coinsFor(q),self:q.type==='text'};saveGuest()}
 state.feedback[q.id]=correct===null?null:correct;render();if(correct===true)toast('Richtig! ⭐ Ihr Lernfortschritt wurde aktualisiert.');}
 catch(e){toast(e.message)}
}
function saveGuest(){localStorage.setItem(STORE,JSON.stringify(state.guest))}
function nextQ(delta){const mod=state.page==='test'?'test':state.module;state.qAt=Math.max(0,Math.min(moduleQ(mod).length-1,state.qAt+delta));render();$('#question')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function importGuest(){
 const entries=Object.entries(state.guest.answers||{}).filter(([id])=>questions.has(id)).map(([id,a])=>({id,answer:a.answer,selfChecked:a.status==='self'}));
 if(!entries.length)return toast('Es gibt keine Gastantworten zum Übertragen.');
 try{
  for(let i=0;i<entries.length;i+=8){const r=await api('import',{entries:entries.slice(i,i+8)});state.user=r.user}
  state.guest=emptyProgress();saveGuest();render();toast('Ihre Gastantworten wurden ins Konto übertragen.');
 }catch(err){toast('Übertragung nicht vollständig: '+err.message)}
}
async function roster(){if(state.user?.role!=='teacher')return;try{const r=await api('roster');state.teacherUsers=r.users;render()}catch(e){toast(e.message)}}
function toPdf(){let entries=Object.entries(progress().answers||{}).filter(([id,a])=>questions.has(id));if(!entries.length)return toast('Sie haben noch keine Aufgabe bearbeitet.');const win=window.open('','_blank');if(!win)return toast('Bitte erlauben Sie das Öffnen der Druckansicht.');const items=entries.map(([id,a],i)=>{const q=questions.get(id);let ans=typeof a.answer==='object'?JSON.stringify(a.answer,null,2):String(a.answer??'');return `<article style="break-inside:avoid;margin:20px 0;border-top:1px solid #ccc;padding:14px 0"><h3>${i+1}. ${esc(q.prompt)} <small>(AFB ${q.afb}${q.bonus?', Bonus':''})</small></h3><div><b>Ihre Antwort:</b><pre>${esc(ans)}</pre></div><div><b>Bewertung:</b> ${a.status==='self'?'Selbst geprüft':a.status==='correct'?'Korrekt':a.status==='wrong'?'Noch nicht korrekt':'Entwurf'}</div><div><b>Musterlösung:</b> ${rich(q.solution)}</div></article>`}).join('');win.document.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Mein Lernjournal – Preisgrenzen</title><style>body{font:13px/1.6 Arial,sans-serif;max-width:780px;margin:35px auto;color:#243843}h1{font-size:23px}h3{font-size:16px}pre{white-space:pre-wrap;font:inherit;background:#f0f4f5;padding:10px}small{color:#607684}article{page-break-inside:avoid}@media print{body{margin:0}}</style></head><body><h1>Preisgrenzen – Mein Lernjournal</h1><p><b>Profil:</b> ${esc(identity())} · <b>Klasse:</b> ${esc(state.user?.schoolClass||'Gast')} · <b>Datum:</b> ${new Date().toLocaleDateString('de-DE')}</p><p>Dokumentierte Aufgaben: ${items.length}. Dieses Dokument enthält Schülerantworten und zugehörige Musterlösungen.</p>${items}<script>window.addEventListener('load',()=>{setTimeout(()=>window.print(),250)})<\/script></body></html>`);win.document.close();}
let dragged=null,orderDragged=null;
document.addEventListener('dragstart',e=>{let tok=e.target.closest('[data-dragtoken]');if(tok){dragged={q:tok.dataset.dragtoken,item:tok.dataset.item};e.dataTransfer?.setData('text/plain',dragged.item);e.dataTransfer.effectAllowed='move'}let row=e.target.closest('[data-orderdrag]');if(row){orderDragged={q:row.dataset.orderdrag,index:Number(row.dataset.idx)};e.dataTransfer?.setData('text/plain','row');e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{const dz=e.target.closest('[data-drop],[data-orderdrag]');if(dz){e.preventDefault();dz.classList.add('dragover')}});
document.addEventListener('dragleave',e=>{e.target.closest('[data-drop]')?.classList.remove('dragover')});
document.addEventListener('drop',e=>{const dz=e.target.closest('[data-drop]');if(dz&&dragged?.q===dz.dataset.drop){e.preventDefault();const q=questions.get(dragged.q);let map={...currentDraft(q)};if(dz.dataset.group)map[dragged.item]=dz.dataset.group;else delete map[dragged.item];state.draft[q.id]=map;dragged=null;render();return}const row=e.target.closest('[data-orderdrag]');if(row&&orderDragged?.q===row.dataset.orderdrag){e.preventDefault();const q=questions.get(orderDragged.q),lst=[...currentDraft(q)],to=Number(row.dataset.idx),from=orderDragged.index;lst.splice(to,0,lst.splice(from,1)[0]);state.draft[q.id]=lst;orderDragged=null;render()}});
document.addEventListener('input',e=>{if(e.target.dataset.draft)state.draft[e.target.dataset.draft]=e.target.value;
 if(e.target.id==='gloss'){state.gloss=e.target.value;const el=$('#glossgrid');if(el)el.innerHTML=glossaryCards()}
 if(e.target.dataset.slider){const k=e.target.dataset.slider;state.labs[k]=Number(e.target.value);const out=$('#o-'+k);if(out)out.textContent=fmt(state.labs[k])+' '+(['x','qty'].includes(k)?'Stück':['fixedPercent','mgk','fgk','vw','vt','fixShare'].includes(k)?'%':'€');renderLabOutput()}});
document.addEventListener('change',async e=>{const el=e.target;
 if(el.dataset.choice){const q=questions.get(el.dataset.choice);if(q.type==='multi')state.draft[q.id]=[...document.querySelectorAll(`[data-choice="${q.id}"]:checked`)].map(x=>x.value);else state.draft[q.id]=q.type==='truefalse'?el.value==='true':el.value;return}
 if(el.dataset.map){const id=el.dataset.map,q=questions.get(id),d={...currentDraft(q)};if(el.value)d[el.dataset.item]=el.value;else delete d[el.dataset.item];state.draft[id]=d;render();return}
 if(el.dataset.rating){const idx=Number(el.dataset.rating),val=Number(el.value),prev=progress().checklist[idx]||{done:false};try{if(state.user){const r=await api('checklist',{index:idx,value:val,done:prev.done});state.user=r.user}else{state.guest.checklist[idx]={value:val,done:prev.done};saveGuest()}render()}catch(err){toast(err.message)}}
});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='authform'){const b=Object.fromEntries(new FormData(e.target).entries());state.lastClass=b.schoolClass;try{const r=await api(state.authMode==='register'?'register':'login',b);state.user=r.user;state.modal=null;state.draft={};state.feedback={};state.revealed={};route('home');toast('Willkommen! Ihr Fortschritt wird auf Netlify gespeichert.');if(state.user.role==='teacher')await roster()}catch(err){toast(err.message)}return}
 if(e.target.id==='passwordform'){const b=Object.fromEntries(new FormData(e.target).entries());try{await api('password',b);state.user=null;state.modal=null;render();toast('Passwort geändert. Bitte melden Sie sich erneut an.')}catch(err){toast(err.message)}return}});
document.addEventListener('click',async e=>{
 const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.nav){route(btn.dataset.nav);if(btn.dataset.nav==='teacher')await roster();return}
 if(btn.dataset.module){route(btn.dataset.module==='test'?'test':'lesson',btn.dataset.module);return}
 if(btn.dataset.qIndex!==undefined){state.qAt=Number(btn.dataset.qIndex);render();$('#question')?.scrollIntoView({block:'start',behavior:'smooth'});return}
 if(btn.dataset.qnext){nextQ(1);return}if(btn.dataset.qprev){nextQ(-1);return}
 if(btn.dataset.lab){state.lab=btn.dataset.lab;render();return}
 if(btn.dataset.move){let q=questions.get(btn.dataset.move),arr=[...currentDraft(q)],from=Number(btn.dataset.pos),to=from+Number(btn.dataset.dir);if(to<0||to>=arr.length)return;[arr[from],arr[to]]=[arr[to],arr[from]];state.draft[q.id]=arr;render();return}
 if(btn.dataset.buy){let item=products.get(btn.dataset.buy);if(!item)return;try{if(state.user){const r=await api('shop',{id:item.id});state.user=r.user}else{let ss=summary();if(levelFromXP(ss.xp)<item.level||ss.coins<item.cost)return toast('Level oder Münzen reichen nicht aus.');if(progress().owned.includes(item.id))return;state.guest.owned.push(item.id);saveGuest()}render();toast('Neuer Gegenstand freigeschaltet: '+item.name)}catch(err){toast(err.message)}return}
 if(btn.dataset.equip){let item=products.get(btn.dataset.equip);try{if(state.user){const r=await api('equip',{id:item.id});state.user=r.user}else{state.guest.equipped[item.kind]=item.id;saveGuest()}render();toast('Ausgerüstet: '+item.name)}catch(err){toast(err.message)}return}
 if(btn.dataset.check!==undefined){const index=Number(btn.dataset.check),done=btn.dataset.done==='true',val=progress().checklist[index]?.value||3;try{if(state.user){const r=await api('checklist',{index,value:val,done});state.user=r.user}else{state.guest.checklist[index]={value:val,done};saveGuest()}render()}catch(err){toast(err.message)}return}
 if(btn.dataset.student){state.teacherSelected=btn.dataset.student;render();return}
 if(btn.dataset.teacherOp){const mode=btn.dataset.teacherOp,nickname=btn.dataset.nickname;openModal('confirmTeacher',{mode,nickname,message:mode==='remove'?`Das Schülerkonto ${nickname} und sein Lernfortschritt werden gelöscht.`:mode==='resetPassword'?`Für ${nickname} wird ein neues temporäres Passwort erzeugt. Das bisherige Passwort ist danach ungültig.`:`Der Lernfortschritt von ${nickname} wird unwiderruflich zurückgesetzt.`});return}
 const action=btn.dataset.action;
 if(action==='auth'){openModal('auth');return}
 if(action==='auth-toggle'){state.authMode=state.authMode==='register'?'login':'register';render();return}
 if(action==='account'){openModal('account');return}
 if(action==='close-modal'){state.modal=null;render();return}
 if(action==='reveal'){state.revealed[btn.dataset.q]=true;state.modal=null;render();return}
 if(action==='solution-request'){openModal('confirm',{q:btn.dataset.q});return}
 if(action==='hint'){state.hint[btn.dataset.q]=!state.hint[btn.dataset.q];render();return}
 if(action==='submit'){await submit(questions.get(btn.dataset.q));return}
 if(action==='selfcorrect'){await submit(questions.get(btn.dataset.q),'correct');return}
 if(action==='selfrevise'){state.revealed[btn.dataset.q]=false;state.feedback[btn.dataset.q]=undefined;render();$('#question')?.scrollIntoView({block:'start',behavior:'smooth'});return}
 if(action==='importguest'){state.modal=null;await importGuest();return}
 if(action==='print'){toPdf();return}
 if(action==='refresh-roster'){await roster();return}
 if(action==='logout'){try{await api('logout',{});state.user=null;state.modal=null;state.teacherUsers=[];route('home');toast('Sie wurden abgemeldet.')}catch(err){toast(err.message)}return}
 if(action==='reset-class'){openModal('confirmTeacher',{mode:'resetClass',message:'ALLE Lernstände Ihrer Klasse werden unwiderruflich gelöscht. Die Schülerkonten bleiben bestehen.'});return}
 if(action==='teacher-execute'){const {mode,nickname}=state.modal;try{const r=await api('teacher',{mode,nickname});state.modal=r.temporaryPassword?{type:'tempPassword',value:r.temporaryPassword}:null;state.teacherSelected=null;await roster();toast(r.notice||'Aktion abgeschlossen.')}catch(err){toast(err.message)}return}
 if(action==='copytemp'){const t=state.modal?.value;if(t)try{await navigator.clipboard.writeText(t);toast('Passwort kopiert.')}catch{toast('Kopieren nicht möglich: Passwort manuell übertragen.')}return}
});
(async()=>{render();try{const r=await api('me');if(r.user){state.user=r.user;render()}}catch{ /* Guest version remains usable without server */}})();
